function seal(rows){const counts=Object.fromEntries(countKeys.map(k=>[k,0]));counts.schemas=[...SCOPE].sort();for(const r of rows)if(counters[r.kind])counts[counters[r.kind]]++;const body={schema:SCHEMA_VERSION,postgres_major:18,scope:[...SCOPE],sql_sha256:SQL_SHA256,counts,records:sort(rows)};return{...body,sha256:sha(JSON.stringify(canonical(body)))};}
