 assert.equal(origin.candidate_bytes,3568271);assert.equal(origin.sealed,false);assert.equal(origin.business_acceptance,false);assert.equal(origin.status,'SOURCE_EXPECTATION_PREPARED_NOT_COMPILED');assert.equal(origin.source_vector_canonical_sha256,'bd91867d55ba24aa72541e2a2714eb7547a3ba9b9ab245a18817d41cf115738b');assert.equal(origin.source_expectation_result_sha256,'49d035f576224ec405bbeff14be545ec70ee898b3c9dcf2bdc4ef9472ee16631');assert.equal(parentOrigin.decoded_sha256,'121abfe5df79f03f9d3acd38e566bbcf53c18ec0b4bf418c316632138cd37070');assert.deepEqual(expected.inactive_ancestors,[{kind:'function',key:'public.buyer_address_guards()',value:parent209.changes.find(r=>r.key==='public.buyer_address_guards()').before}]);assert.equal(origin.decoded_bytes,1362195);assert(origin.gzip_bytes===121030);assert(Object.isFrozen(expected.additions[0].value));
