test('all493 complete source additions and15 complete replacements invert exactly, including canonical AND reader serialization and eight counts',()=>{
 const f=fixture(),saved=JSON.stringify(f.after),before=validateRecoverySchema(f.before),r=project(f.after,expected);
 assert.equal(r.mode,'active210_inverse');assert.equal(r.active,true);assert.equal(r.removed_records,493);assert.equal(r.changed_records,15);assert.equal(r.authority,false);
 assert.equal(r.catalogue.sha256,before.sha256);assert.equal(JSON.stringify(r.catalogue),JSON.stringify(before));assert.equal(compareRecoverySchemas(r.catalogue,before).equal,true);
 assert.equal(JSON.stringify(f.after),saved);assert(!Object.isFrozen(f.after));assert(Object.isFrozen(r.catalogue));
 for(const [kind,n]of Object.entries(ORDER_SPLIT210_ADDITION_COUNTS)){assert.equal(r.removed_counts[counters[kind]],n);assert.equal(r.catalogue.counts[counters[kind]],f.after.counts[counters[kind]]-n);}
 assert.throws(()=>inspectPackingCatalogueContext(r.catalogue),/owned-catalogue-required/);
});
